def make_entry(account: str, amount_cents: int) -> dict:
    if amount_cents < 0:
        raise ValueError("amount_cents must be non-negative")
    return {"account": account, "amount_cents": amount_cents}

import inspect

import pytest

from ledger.entries import make_entry


def test_amount_parameter_has_explicit_unit():
    assert list(inspect.signature(make_entry).parameters) == ["account", "amount_cents"]


@pytest.mark.parametrize("amount_cents", [0, 1, 1250])
def test_make_entry_accepts_non_negative_amounts(amount_cents):
    assert make_entry(account="cash", amount_cents=amount_cents) == {
        "account": "cash",
        "amount_cents": amount_cents,
    }


def test_make_entry_accepts_positional_amount():
    assert make_entry("cash", 1250) == {"account": "cash", "amount_cents": 1250}


@pytest.mark.parametrize("amount_cents", [-1, -1250])
def test_make_entry_rejects_negative_amounts(amount_cents):
    with pytest.raises(ValueError):
        make_entry("cash", amount_cents)
